// Authored content for 3.2.1.1 Pathogens (OxfordAQA 9610 v5.1, printed p.22; statements 3.2.1.1.s1–s3 in data/spec.js).
// Official wording: "Pathogens are agents of infection and include bacteria and viruses. Disease can result when
// pathogens penetrate any of an organism's interfaces with the environment. In a mammal these include the digestive,
// reproductive and gas-exchange systems. Pathogens cause disease by damaging the cells of the host and by producing
// toxins." Everything beyond that wording is labelled supporting, extension or stretch and challenge on the page. Examples were chosen to be
// accurate and checkable at AS level; the mechanism of cholera itself is taught in 3.2.3.1 and HIV in 3.2.4.
// Interactives: disEntry (Pathogen Entry Explorer) and disMechanism (Disease Mechanism Challenge), in
// js/views/interactives-disease.js.
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.diseaseArt;
  const R = "3.2.1.1";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const P = (slot) => window.BIO.views.photo(slot);
  // Specification status of named pathogens (teacher decisions d30/d31, 2026-11-07): the specification names only
  // cholera (3.2.3) and HIV (3.2.4). Every other named pathogen is a stretch and challenge example.
  const SC = `<span class="badge navy" title="beyond the specification: an example, not something to learn">stretch and challenge</span>`;
  const ON = (r) => `<span class="badge teal" title="named in the specification">on the specification: ${r}</span>`;
  const SCKEY = `<span class="badge navy">stretch and challenge</span> beyond the specification: an example to show the idea, not something to learn. <span class="badge teal">on the specification</span> named in the specification: cholera (3.2.3) and HIV (3.2.4) are the only diseases it names.`;
  const tbl = (head, rows) => `<table class="tbl"><thead><tr>${head.map((x) => `<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;

  // ---------------------------------------------------------------- A. Pathogen Entry Explorer ----------------------------------------------------------------
  const entry = { kind: "disEntry", title: "Pathogen Entry Explorer", note: "Select an interface on the body (click, or Tab to it and press Enter or Space), or use the buttons. Each panel explains why that surface can be crossed, gives checked examples of bacteria and viruses that enter there, and asks you to explain what you see. The skin is not one of the three systems named in the specification, so it is marked supporting. Each example is labelled: cholera and HIV are on the specification (3.2.3, 3.2.4); every other pathogen is a stretch and challenge example (beyond the specification: an example, not something to learn).",
    items: [
      { zone: "gas", level: "required", title: "Gas-exchange system",
        why: "The airways and alveoli are open to the air you breathe in. The alveolar surface is very large, thin and moist, so it is good for diffusion of gases, but it also gives pathogens carried in airborne droplets a large surface to reach and cross.",
        defences: "Mucus traps particles and pathogens and cilia sweep the mucus up to the throat; phagocytes (alveolar macrophages) engulf pathogens that reach the alveoli (supporting; immunity is 3.2.5).",
        examples: [
          { name: "Influenza virus", type: "virus", route: "Breathed in as droplets from an infected person's coughs and sneezes.", effect: "Infects epithelial cells lining the airways and uses them to make new virus particles; infected cells are damaged and die." },
          { name: "Mycobacterium tuberculosis", type: "bacterium", route: "Breathed in as tiny droplets; can reach the alveoli.", effect: "Taken up by macrophages and survives inside them; much of the lung damage in tuberculosis comes from the immune response to the bacteria." },
        ],
        questions: [
          { id: `q-${R}-ie1`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Entry Explorer, gas-exchange system. Which feature of the alveoli makes them good for gas exchange but also a possible route for pathogens?", options: ["A very large, thin, moist surface in contact with inhaled air", "A thick layer of dead, keratinised cells", "A strongly acidic secretion", "A coat of mucus moved along by cilia"], answer: 0, explanation: "The features that speed up diffusion (large area, thin, moist) also mean airborne pathogens that reach the alveoli meet a large exposed surface. Mucus and cilia are a defence in the airways, not a feature of the alveoli." },
          { id: `q-${R}-ie2`, ref: R, stmts: S(2, 1), type: "short", marks: 2, stem: "Stretch and challenge. Entry Explorer. Influenza and tuberculosis both enter through the gas-exchange system. Explain how they reach it, and state one difference between the two pathogens. (2 marks)", scheme: [{ point: "Both are breathed in, in droplets / aerosols from an infected person", marks: 1 }, { point: "Difference: influenza is a virus, tuberculosis is caused by a bacterium (Mycobacterium tuberculosis); or influenza infects airway epithelial cells while M. tuberculosis is taken up by and survives in macrophages", marks: 1 }], model: "Both pathogens are breathed in, carried in droplets or aerosols released when an infected person coughs, sneezes or breathes out. Influenza is a virus that infects the epithelial cells lining the airways, whereas tuberculosis is caused by a bacterium, Mycobacterium tuberculosis, which reaches the alveoli and survives inside macrophages.", commonErrors: "Calling both of them viruses; saying they enter through the blood." },
        ] },
      { zone: "dig", level: "required", title: "Digestive system",
        why: "Food and water are taken in and absorbed across the lining of the intestine, which has a very large surface area (villi and microvilli; see 3.2.2.3). Pathogens swallowed in contaminated food or water can multiply in the gut, attach to or invade its lining, or release toxins there.",
        defences: "Hydrochloric acid in the stomach kills many swallowed microorganisms, and the many harmless bacteria already living in the gut compete with pathogens (supporting).",
        examples: [
          { name: "Vibrio cholerae", type: "bacterium", spec: "3.2.3", route: "Swallowed in water or food contaminated with faeces from an infected person.", effect: "Multiplies in the small intestine and secretes cholera toxin, which makes the epithelial cells secrete chloride ions; water follows and severe diarrhoea results (3.2.3.1). The cells are not destroyed." },
          { name: "Poliovirus", type: "virus", route: "Swallowed in faecally contaminated water or food.", effect: "Multiplies in the throat and intestine; in a small proportion of infections it reaches the nervous system, where it destroys motor neurones, causing paralysis." },
          { name: "Rotavirus", type: "virus", route: "Swallowed (faecal–oral route); a common cause of diarrhoea in young children.", effect: "Infects and kills epithelial cells at the tips of the villi in the small intestine, reducing the absorption of water and nutrients." },
        ],
        questions: [
          { id: `q-${R}-ie3`, ref: R, stmts: S(2, 3), type: "mcq", marks: 1, stem: "Stretch and challenge. Entry Explorer, digestive system. Vibrio cholerae and rotavirus both cause diarrhoea after entering through the digestive system. Which statement is correct?", options: ["Vibrio cholerae acts mainly through a toxin; rotavirus kills epithelial cells at the tips of the villi", "Both act only by bursting epithelial cells", "Both act only through toxins secreted into the blood", "Neither crosses an interface with the environment"], answer: 0, explanation: "Two pathogens entering by the same route can cause disease in different ways: cholera toxin changes what the cells do without destroying them, while rotavirus kills villus cells." },
          { id: `q-${R}-ie4`, ref: R, stmts: S(2), type: "short", marks: 2, stem: "Stretch and challenge. Entry Explorer. Suggest why most cases of cholera and poliomyelitis occur where drinking water is not separated from sewage. (2 marks)", scheme: [{ point: "Both pathogens leave an infected person in faeces", marks: 1 }, { point: "They are swallowed in contaminated water, so they enter through the digestive system (faecal–oral route)", marks: 1 }], model: "Vibrio cholerae and poliovirus are both shed in the faeces of infected people. Where sewage gets into drinking water, other people swallow the pathogens, which enter the body through the digestive system.", commonErrors: "Saying the pathogens are breathed in." },
        ] },
      { zone: "rep", level: "required", title: "Reproductive system",
        why: "The linings of the vagina, cervix, penis and urethra are mucous membranes: thin, moist surfaces without the tough dead outer layer of the skin. During sexual intercourse pathogens in body fluids can come into contact with, and cross, these membranes.",
        defences: "In the vagina, harmless bacteria (lactobacilli) keep the conditions acidic, which slows the growth of many pathogens (supporting).",
        examples: [
          { name: "Human immunodeficiency virus (HIV)", type: "virus", spec: "3.2.4", route: "Mainly in semen or vaginal fluid during sexual intercourse; also in blood (e.g. shared needles) and from mother to baby.", effect: "Infects helper T cells and, over years, destroys them, weakening the immune system (3.2.4)." },
          { name: "Chlamydia trachomatis", type: "bacterium", route: "Sexual contact.", effect: "Multiplies inside epithelial cells of the reproductive tract; inflammation can scar the oviducts (fallopian tubes) and cause infertility." },
          { name: "Human papillomavirus (HPV)", type: "virus", route: "Sexual contact.", effect: "Infects epithelial cells of the cervix; long-lasting infection with some types is a risk factor for cervical cancer (a link to 3.2.1.2)." },
        ],
        questions: [
          { id: `q-${R}-ie5`, ref: R, stmts: S(2, 1), type: "mcq", marks: 1, stem: "Stretch and challenge. Entry Explorer, reproductive system. Which pair are both pathogens that commonly enter through the reproductive system?", options: ["HIV (a virus) and Chlamydia trachomatis (a bacterium)", "Influenza virus and Mycobacterium tuberculosis", "Vibrio cholerae and rotavirus", "Clostridium tetani and influenza virus"], answer: 0, explanation: "HIV and Chlamydia are sexually transmitted; the others enter through the gas-exchange or digestive systems or through wounds." },
          { id: `q-${R}-ie6`, ref: R, stmts: S(2), type: "short", marks: 2, stem: "Entry Explorer. Explain why the lining of the vagina is easier for pathogens to cross than the skin on the arm. (2 marks)", scheme: [{ point: "The vaginal lining is a thin, moist mucous membrane", marks: 1 }, { point: "The skin has a tough / thick outer layer of dead (keratinised) cells, which pathogens cannot easily cross unless it is broken", marks: 1 }], model: "The vagina is lined by a thin, moist mucous membrane made of living cells, which pathogens in body fluids can reach and cross. Intact skin has a thick, tough outer layer of dead cells that forms a barrier, so pathogens usually enter through the skin only where it is cut or bitten.", commonErrors: "Saying the vagina has a larger surface area than the skin." },
        ] },
      { zone: "skin", level: "supporting", title: "Skin (when broken)",
        why: "Intact skin is a tough barrier: its outer layer is made of dead cells. Cuts, bites, burns and needles break it and let pathogens into the tissues underneath. The specification says 'include', so the three named systems are not the only interfaces.",
        defences: "The dead outer layer and the skin's own harmless bacteria; blood clotting seals wounds (supporting).",
        examples: [
          { name: "Clostridium tetani", type: "bacterium", route: "Spores from soil enter a wound, often a deep puncture wound.", effect: "Grows in the wound and releases tetanus toxin, which travels to the nervous system and blocks the release of neurotransmitters that normally inhibit motor neurones, so muscles contract uncontrollably in painful spasms." },
          { name: "Rabies virus", type: "virus", route: "In the saliva of an infected animal, through a bite.", effect: "Travels along nerves to the brain, where it damages nerve cells." },
        ],
        questions: [
          { id: `q-${R}-ie7`, ref: R, stmts: S(2, 3), type: "mcq", marks: 1, stem: "Stretch and challenge. Entry Explorer, skin. Clostridium tetani stays in the wound, yet tetanus causes spasms in muscles all over the body. Why?", options: ["The bacterium releases a toxin that travels to the nervous system", "The bacterium bursts muscle cells all over the body", "The bacterium enters through the gas-exchange system as well", "Tetanus is caused by a virus, not a bacterium"], answer: 0, explanation: "A toxin can act far from where the pathogen is growing: tetanus toxin reaches nerve cells and blocks inhibitory neurotransmitter release." },
        ] },
    ] };

  // ---------------------------------------------------------------- B. Disease Mechanism Challenge ----------------------------------------------------------------
  const CAT = [
    { k: "cell", label: "Damages or kills host cells directly" },
    { k: "toxin", label: "Releases a toxin that harms the host" },
    { k: "both", label: "Both: invades and damages cells and releases a toxin" },
    { k: "immune", label: "Much of the damage comes from the host's own immune response", stretch: true },
    { k: "none", label: "Normally causes no disease", stretch: true },
  ];
  const cases = [
    { id: "chol", label: "Cholera", spec: "3.2.3", name: "Vibrio cholerae (bacterium)", via: "digestive system", story: "Bacteria swallowed in contaminated water attach to the lining of the small intestine and multiply there. They secrete a protein that enters the epithelial cells and makes them secrete chloride ions into the lumen; water follows by osmosis and the person has severe watery diarrhoea. The epithelial cells stay alive and intact.", best: "toxin", accept: ["toxin"], why: "Cholera is toxin-mediated: the cells are not destroyed, their function is changed (details in 3.2.3.1). Only strains that carry the toxin genes cause cholera, so even within one species not every strain is harmful." },
    { id: "tet", label: "Tetanus", name: "Clostridium tetani (bacterium)", via: "skin wound (supporting)", story: "Spores in soil enter a deep wound and grow where there is little oxygen. The bacteria stay in the wound but release a protein that travels to the spinal cord. There it stops nerve cells releasing the neurotransmitters that normally inhibit motor neurones, so muscles contract uncontrollably (spasms, 'lockjaw').", best: "toxin", accept: ["toxin"], why: "A toxin can act far from the pathogen. Tetanus toxin is a neurotoxin; the bacteria themselves do not spread through the body." },
    { id: "polio", label: "Poliomyelitis", name: "Poliovirus (virus)", via: "digestive system", story: "The virus is swallowed and multiplies in the throat and intestine. In a small proportion of infections it reaches the nervous system and infects motor neurones. Each infected neurone makes many new virus particles and then bursts (lysis), releasing them. Destroyed motor neurones cannot stimulate muscles, so paralysis can result.", best: "cell", accept: ["cell"], why: "Poliovirus damages host cells directly: replication inside the cell ends with lysis, killing it. Neurones that are destroyed are not replaced." },
    { id: "flu", label: "Influenza", name: "Influenza virus (virus)", via: "gas-exchange system", story: "Breathed-in virus particles infect epithelial cells lining the airways. Each infected cell is used to make new virus particles, which leave by budding from the cell-surface membrane. The infected cells are damaged and die, and the lining of the airways is lost in patches.", best: "cell", accept: ["cell", "immune"], why: "Influenza damages host cells directly. Note that it buds rather than bursting the cell, yet the cells still die: 'damaging cells' does not always mean lysis. The immune response also contributes to symptoms (fever, inflammation), so that answer is partly right." },
    { id: "shig", label: "Bacillary dysentery", name: "Shigella dysenteriae type 1 (bacterium)", via: "digestive system", story: "Bacteria swallowed in contaminated food or water invade the epithelial cells lining the colon, multiply inside them and spread from cell to cell, destroying the lining; this causes bloody diarrhoea. This type also produces Shiga toxin, which can damage cells elsewhere, including in the kidneys.", best: "both", accept: ["both"], why: "One pathogen can do both: invasion destroys colon cells, and Shiga toxin causes further damage. Categories are not mutually exclusive." },
    { id: "tb", label: "Tuberculosis", name: "Mycobacterium tuberculosis (bacterium)", via: "gas-exchange system", story: "Breathed-in bacteria are engulfed by macrophages in the alveoli but survive and multiply inside them. The immune system walls off infected areas; over time, the immune response destroys lung tissue in these areas, leaving cavities. The bacteria do not rely on a toxin of the cholera or tetanus kind.", best: "immune", accept: ["immune", "cell"], why: "Much of the tissue damage in tuberculosis is caused by the host's own immune response. The bacteria also kill some of the macrophages they live in, so 'damages host cells' is partly right." },
    { id: "staph", label: "Staphylococcal food poisoning", name: "Staphylococcus aureus (bacterium)", via: "digestive system (toxin in food)", story: "Bacteria from a food handler's skin grow in food left warm, and release a heat-stable toxin into the food. Someone eats the food after it has been reheated: the bacteria are now dead, but within a few hours the person is vomiting.", best: "toxin", accept: ["toxin"], why: "Here the toxin was made in the food before it was eaten, so illness does not even need living bacteria in the body. This shows why 'pathogens must multiply inside you to make you ill' is not a safe generalisation." },
    { id: "hiv", label: "HIV infection", spec: "3.2.4", name: "Human immunodeficiency virus (virus)", via: "reproductive system (also blood)", story: "The virus infects helper T cells and uses them to make new virus particles, which bud from the cell. Over several years the number of helper T cells falls, the immune system weakens and other infections take hold (AIDS).", best: "cell", accept: ["cell"], why: "HIV damages host cells directly by destroying helper T cells (3.2.4). The illness that follows is caused by other pathogens, because the immune system can no longer respond well." },
    { id: "rota", label: "Rotavirus diarrhoea", name: "Rotavirus (virus)", via: "digestive system", story: "Swallowed virus particles infect the mature epithelial cells at the tips of the villi in the small intestine and kill them, so less water and fewer nutrients are absorbed. Extension: one rotavirus protein (NSP4) also acts like a toxin, increasing the secretion of chloride ions.", best: "cell", accept: ["cell", "both"], why: "At AS level, rotavirus damages host cells directly (villus cells killed). The extension detail shows that even viruses can make toxin-like proteins, so 'both' is also defensible; never assume that toxins are made only by bacteria." },
    { id: "chla", label: "Chlamydia", name: "Chlamydia trachomatis (bacterium)", via: "reproductive system", story: "The bacteria can only multiply inside host cells. They infect epithelial cells of the cervix or urethra and are released when the cell breaks open. Repeated or long-lasting infection causes inflammation that can scar the oviducts, blocking them and causing infertility.", best: "immune", accept: ["immune", "cell"], why: "The bacteria do kill the cells they multiply in, but the long-term damage (scarring) comes mainly from the inflammatory response. Both answers have support; the scarring is the main harm." },
    { id: "diph", label: "Diphtheria", name: "Corynebacterium diphtheriae (bacterium)", via: "gas-exchange system (upper airways)", story: "Bacteria grow on the lining of the throat but do not invade deeply. Some strains release a toxin that stops host cells making proteins, so cells in the throat die and form a grey layer; the toxin can also reach and damage the heart and nerves.", best: "toxin", accept: ["toxin"], why: "The toxin is what kills the host cells here, so 'damaging cells' and 'producing toxins' overlap: a toxin is one way of damaging cells. Only toxin-producing strains cause diphtheria." },
    { id: "ecoli", label: "Gut E. coli", name: "Escherichia coli, most strains (bacterium)", via: "lives in the large intestine", story: "Most strains of E. coli live in the large intestine of healthy people throughout their lives without causing any illness, alongside many other species of bacteria.", best: "none", accept: ["none"], why: "Most bacteria, including most E. coli strains, are not pathogens. Being a bacterium does not make an organism harmful." },
    { id: "o157", label: "E. coli O157", name: "Escherichia coli O157 (bacterium)", via: "digestive system", story: "This strain, often from undercooked beef or contaminated vegetables, attaches to the lining of the large intestine and releases Shiga toxin, causing bloody diarrhoea; in some patients, especially children, the toxin damages blood vessels and the kidneys.", best: "toxin", accept: ["toxin", "both"], why: "The same species as the harmless gut strains, but this strain produces a toxin. It attaches to and damages the lining at the site too, so 'both' is defensible; the toxin explains the most serious effects." },
  ];
  const myths = [
    { s: "All bacteria cause disease.", t: false, why: "Most bacteria are harmless, and many in the gut are useful; only some species, and often only some strains of a species, are pathogens." },
    { s: "All viruses kill their host cells by bursting them.", t: false, why: "Some viruses (e.g. poliovirus) burst the cell; others (e.g. influenza, HIV) leave by budding, although the infected cells are still damaged." },
    { s: "One pathogen can both damage host cells and release a toxin.", t: true, why: "Shigella dysenteriae type 1 invades and destroys colon cells and also produces Shiga toxin." },
    { s: "A toxin only harms the host while the bacteria that made it are alive in the body.", t: false, why: "Staphylococcus aureus toxin is made in food before it is eaten; it causes vomiting even if the bacteria have been killed." },
    { s: "Some of the damage in an infection can be caused by the host's own immune response.", t: true, why: "In tuberculosis and chlamydia, much of the lasting tissue damage comes from the immune and inflammatory response." },
    { s: "Anyone who takes in a pathogen will become ill.", t: false, why: "Whether disease results depends on the dose, on the body's defences at the interface and on immunity; many exposures cause no illness." },
  ];
  const mech = { kind: "disMechanism", title: "Disease Mechanism Challenge", note: "Thirteen cases, one at a time: twelve pathogens and one gut bacterium that is usually harmless. Read how each one causes harm and choose the description that fits best; some cases have more than one defensible answer and the feedback says why. Then test six generalisations: most sweeping statements about 'all bacteria' or 'all viruses' are false. The specification gives two ways pathogens cause disease (damaging host cells and producing toxins); the extra choices (the host's immune response, and normally causes no disease) are stretch and challenge. Cholera and HIV are on the specification; the other eleven cases are stretch and challenge examples.",
    categories: CAT, items: cases, myths,
    questions: [
      { id: `q-${R}-mc1`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Stretch and challenge. Mechanism Challenge. Which pair of examples best shows that pathogens cause disease in different ways?", options: ["Poliovirus bursts motor neurones; cholera toxin changes the function of intestinal cells without killing them", "Influenza and HIV are both viruses", "Vibrio cholerae and Shigella both enter through the digestive system", "Tuberculosis and diphtheria both affect the gas-exchange system"], answer: 0, explanation: "The first option contrasts host-cell damage with a toxin; the others compare pathogen type or route, not mechanism." },
      { id: `q-${R}-mc2`, ref: R, stmts: S(3, 1), type: "mcq", marks: 1, stem: "Stretch and challenge. Mechanism Challenge. Most strains of E. coli are harmless, but E. coli O157 causes serious illness. What best explains the difference?", options: ["The O157 strain produces Shiga toxin", "E. coli O157 is a virus", "Harmless strains have no DNA", "O157 enters through the gas-exchange system"], answer: 0, explanation: "Strains of one species can differ in whether they carry toxin genes; being a bacterium does not make an organism a pathogen." },
      { id: `q-${R}-mc3`, ref: R, stmts: S(3), type: "short", marks: 3, stem: "Stretch and challenge. Mechanism Challenge. A student writes: 'Viruses damage cells and bacteria produce toxins.' Use two examples to explain why this statement is an oversimplification. (3 marks)", scheme: [{ point: "Some bacteria damage host cells directly, e.g. Shigella invades and destroys colon cells / Chlamydia multiplies inside and kills epithelial cells", marks: 1 }, { point: "Some bacteria do both, or cause damage through the host's immune response (e.g. tuberculosis), or are harmless", marks: 1 }, { point: "Not all viruses burst cells (influenza and HIV bud) / rotavirus has a toxin-like protein (extension); so mechanism must be described pathogen by pathogen", marks: 1 }], model: "Bacteria do not only act through toxins: Shigella invades and destroys the cells lining the colon, and much of the lung damage in tuberculosis comes from the host's immune response rather than a toxin. Many bacteria cause no disease at all. Viruses do damage cells, but in different ways: poliovirus bursts neurones, while influenza and HIV leave by budding, and one rotavirus protein even acts like a toxin. So the mechanism has to be described for each pathogen.", commonErrors: "Giving examples that agree with the statement (e.g. cholera toxin) without any counter-example." },
      { id: `q-${R}-mc4`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Mechanism Challenge. Diphtheria toxin stops host cells making proteins, so the cells die. What does this example show?", options: ["Producing a toxin can be the way a pathogen damages host cells, so the two mechanisms overlap", "Toxins never kill cells", "Diphtheria is caused by a virus", "Only viruses damage host cells"], answer: 0, explanation: "The specification's two mechanisms are not exclusive: a toxin may kill cells (diphtheria) or only change their function (cholera)." },
    ] };

  window.BIO.content[R] = {
    status: "draft",
    banner: "virus-tem", bannerText: "Bacteria and viruses that cross the body's surfaces: how they get in, and how they cause harm once they are there.",
    keywords: ["pathogen", "agent of infection", "infectious disease", "communicable", "non-infectious", "bacterium", "virus", "prokaryote", "capsid", "interface", "gas-exchange system", "digestive system", "reproductive system", "mucous membrane", "toxin", "lysis", "host cell", "Vibrio cholerae", "cholera toxin", "Clostridium tetani", "tetanus toxin", "influenza", "tuberculosis", "poliovirus", "rotavirus", "HIV", "Chlamydia", "HPV", "E. coli", "Staphylococcus aureus"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.2.1.1).</strong> <strong>Pathogens are agents of infection</strong> and include <strong>bacteria and viruses</strong>. Disease can result when pathogens <strong>penetrate any of an organism's interfaces with the environment</strong>; in a mammal these include the <strong>digestive, reproductive and gas-exchange systems</strong>. Pathogens cause disease by <strong>damaging the cells of the host</strong> and by <strong>producing toxins</strong>. Labels: <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">extension</span><br><strong>Named pathogens.</strong> ${SCKEY}</div>

<h2 data-stmt="${R}.s1">1. Infectious and non-infectious disease <span class="badge">supporting</span></h2>
<p>A <strong>disease</strong> is a condition that impairs the normal functioning of an organism. Diseases fall into two broad groups, and this topic deals with both:</p>
${tbl(["", "Infectious (communicable) disease", "Non-infectious (non-communicable) disease"], [["Cause", "A <strong>pathogen</strong> that has entered the body", "Not caused by a pathogen passed from person to person; usually several interacting factors (lifestyle, age, genes, environment)"], ["Spread", "Can be passed from one person (or animal) to another", "Cannot be caught from someone else"], ["Examples", `Cholera ${ON("3.2.3")}, HIV infection ${ON("3.2.4")}; tuberculosis, influenza ${SC}`, "Coronary heart disease, most cancers (3.2.1.2)"]])}
<p>The boundary is not perfectly sharp: a cancer is not infectious, but infection with some pathogens contributes to certain cancers. ${SC} For example, long-lasting infection with high-risk types of human papillomavirus (HPV) is found in almost all cervical cancers, yet most HPV infections clear and never lead to cancer. Infection is needed but is not enough on its own: other factors, such as smoking and the immune response, affect whether cancer develops. This is why 3.2.1.2 describes cancers in terms of several <em>risk factors</em> acting together.</p>

<h2 data-stmt="${R}.s1">2. Pathogens: bacteria and viruses <span class="badge teal">required</span></h2>
<p>A <strong>pathogen</strong> is an <strong>agent of infection</strong>: a microorganism (or virus) that can enter a host and cause disease. The specification names <strong>bacteria</strong> and <strong>viruses</strong>. ${SC} Some fungi (for example the fungi that cause athlete's foot) and some protoctists (for example <em>Plasmodium</em>, which causes malaria) are also pathogens.</p>
<div class="figure"><div class="fig-view">${A.pathogenCompareFig()}</div></div>
${tbl(["Feature", "Bacteria", "Viruses"], [["Nature", "Prokaryotic <strong>cells</strong> (3.1.2.2)", "<strong>Not cells</strong>: genetic material inside a protein coat"], ["Size (typical)", "About 1–5 µm long", "Most about 20–300 nm across"], ["Genetic material", "Circular DNA free in the cytoplasm; often plasmids", "DNA <strong>or</strong> RNA, inside a capsid"], ["Ribosomes, metabolism", "Own 70S ribosomes; carry out their own metabolism", "None; use the host cell's ribosomes and enzymes"], ["Reproduction", "By binary fission (3.2.10.3), outside or inside host cells", "Only inside a host cell, which makes new virus particles"], ["Other structures", "Cell wall, cell-surface membrane; some have capsules and flagella", "Attachment proteins; some have a lipid envelope"]])}
<p class="small">The size ranges are typical values for teaching: there are unusually small bacteria and unusually large viruses.</p>
<div class="notice amber"><strong>Most bacteria are not pathogens.</strong> The human large intestine contains huge numbers of bacteria, most of them harmless or useful. Even within one species, some strains cause disease and others do not: ${SC} most strains of <em>Escherichia coli</em> in the gut are harmless, while <em>E. coli</em> O157 produces a toxin and causes serious illness. Never write that bacteria "cause disease" as if all of them do.</div>
${P("bacteria-sem")}

<h2 data-stmt="${R}.s2">3. Interfaces with the environment <span class="badge teal">required</span></h2>
<p>An organism exchanges materials with its surroundings across <strong>interfaces</strong>: surfaces where the inside of the body meets the outside world. Disease can result when pathogens <strong>penetrate</strong> any of these interfaces. In a mammal they <strong>include the digestive, reproductive and gas-exchange systems</strong>. These surfaces are usually <strong>thin, moist and in direct contact with material from outside</strong> (air, food, water or body fluids from another person), and the gas-exchange and digestive surfaces are also very large, all of which helps exchange but also gives pathogens a way in.</p>
<div class="figure"><div class="fig-view">${A.interfacesFig()}</div></div>
${tbl(["Interface", "How pathogens reach it", "Examples (type)", "Some defences <span class='badge'>supporting</span>"], [
  ["<strong>Gas-exchange system</strong>", "Breathed in, in droplets or aerosols from an infected person", `Influenza virus (virus); <em>Mycobacterium tuberculosis</em> (bacterium) ${SC}`, "Mucus and cilia in the airways; phagocytes in the alveoli"],
  ["<strong>Digestive system</strong>", "Swallowed in contaminated food or water (often the faecal–oral route)", `Cholera bacteria, <em>Vibrio cholerae</em> ${ON("3.2.3")}; poliovirus, rotavirus (viruses) ${SC}`, "Stomach acid; harmless gut bacteria compete with pathogens"],
  ["<strong>Reproductive system</strong>", "Sexual contact: pathogens in body fluids reach thin mucous membranes", `HIV (virus) ${ON("3.2.4")}; HPV (virus), <em>Chlamydia trachomatis</em> (bacterium) ${SC}`, "Acidic conditions in the vagina maintained by harmless bacteria"],
  ["Skin <span class='badge'>supporting</span>", "Through breaks: cuts, bites, burns, needles", `<em>Clostridium tetani</em> (bacterium); rabies virus (virus) ${SC}`, "Tough outer layer of dead cells; blood clotting"]])}
<p>Entry does not guarantee disease. Whether a person becomes ill depends on how many pathogens enter, the defences at that interface and the person's immunity (3.2.5). <span class="badge">supporting</span></p>

<h2 data-stmt="${R}.s3">4. How pathogens cause disease <span class="badge teal">required</span></h2>
<p>Once inside, pathogens cause disease in two main ways, and many pathogens do both.</p>
<div class="figure"><div class="fig-view">${A.mechanismsFig()}</div></div>
<h3>(a) Damaging the cells of the host</h3>
<ul><li><strong>Viruses</strong> enter host cells and use the cell's ribosomes, enzymes and ATP to make new virus particles. Many viruses leave by making the cell <strong>burst (lysis)</strong>, which kills it: ${SC} poliovirus destroys motor neurones in this way, causing paralysis. Others leave by <strong>budding</strong> from the cell-surface membrane (influenza ${SC}, HIV), but the infected cells are still damaged and many die: ${ON("3.2.4")} HIV destroys helper T cells over several years.</li>
<li><strong>Some bacteria</strong> invade host cells or tissues and damage them: ${SC} <em>Shigella</em> invades and destroys the cells lining the colon, causing dysentery; <em>Chlamydia</em> multiplies inside epithelial cells and is released when they break open.</li>
<li>When cells are killed, the tissue cannot do its job: ${SC} rotavirus kills absorptive cells at the tips of the villi, so less water and fewer nutrients are absorbed.</li></ul>
<h3>(b) Producing toxins</h3>
<p>A <strong>toxin</strong> is a poisonous molecule, often a protein, released by a pathogen. Toxin production is best known in bacteria, and only some bacteria (often only some strains) make toxins.</p>
<ul><li>${ON("3.2.3")} <strong>Cholera toxin</strong> (<em>Vibrio cholerae</em>) acts where it is made: it enters the epithelial cells of the small intestine and makes them secrete more chloride ions; water follows by osmosis, giving severe diarrhoea. The cells are <strong>not destroyed</strong>; their function is changed (the mechanism is 3.2.3.1).</li>
<li>${SC} <strong>Tetanus toxin</strong> (<em>Clostridium tetani</em>) acts far from where it is made: the bacteria stay in a wound, but the toxin travels to the nervous system and stops the release of neurotransmitters that normally inhibit motor neurones (the nerve cells that stimulate muscles), so muscles contract uncontrollably in painful spasms.</li>
<li>${SC} Some toxins kill host cells (diphtheria toxin stops cells making proteins), so the two mechanisms overlap. Some are made in food before it is eaten: <em>Staphylococcus aureus</em> toxin causes vomiting even if the bacteria have been killed by reheating.</li></ul>
<h3>(c) Other contributions to damage ${SC}</h3>
<p>Some of the harm in an infection comes from the <strong>host's own immune response</strong>: much of the lung damage in tuberculosis, and the scarring of the oviducts after chlamydia, is caused by inflammation. <span class="badge amber">extension</span> The outer membrane of some bacteria contains lipopolysaccharide (endotoxin), which triggers inflammation and fever; one rotavirus protein, NSP4, acts as a toxin, so toxins are not made only by bacteria.</p>

<h2 data-stmt="${R}.s1 ${R}.s3">5. Writing about pathogens accurately <span class="badge">supporting</span></h2>
<ul><li><strong>Name the pathogen and its type</strong> (virus or bacterium), then the <strong>interface</strong> it crosses, then the <strong>mechanism</strong>: for example "<em>Vibrio cholerae</em>, a bacterium, is swallowed in contaminated water and secretes a toxin in the small intestine".</li>
<li>Avoid sweeping statements: not all bacteria cause disease; not all viruses burst cells; toxins are not the only way bacteria cause harm; one pathogen can damage cells and produce a toxin.</li>
<li>Use <strong>"damage host cells"</strong> precisely: say how (lysis, invasion, killing absorptive cells), not just "attack the body".</li></ul>
${P("virus-tem")}`,
    diagrams: [
      { id: "d-3.2.1.1-1", title: "A mammal's interfaces with the environment", status: "reviewed", caption: "Pathogens can enter where the body meets the outside world. The specification names the gas-exchange, digestive and reproductive systems; broken skin is a further route (supporting). Schematic; organs simplified.", alt: "Outline of a human body. Blue: nose, trachea and lungs, labelled gas-exchange system. Amber: oesophagus, stomach and intestine, labelled digestive system. Red: a small structure in the pelvis, labelled reproductive system. Green: a cut on the arm, labelled skin when broken.", svg: A.interfacesFig() },
      { id: "d-3.2.1.1-2", title: "Bacteria and viruses compared", status: "reviewed", caption: "A bacterium is a prokaryotic cell with its own ribosomes and DNA; a virus particle is genetic material (DNA or RNA) inside a protein capsid, with attachment proteins and, in some viruses, an envelope. Not to scale.", alt: "Left: a rod-shaped bacterium with labelled cell wall, cell-surface membrane, circular DNA, a plasmid, ribosomes and a flagellum. Right: a hexagonal capsid with genetic material inside, surrounded by a dashed envelope bearing attachment proteins.", svg: A.pathogenCompareFig() },
      { id: "d-3.2.1.1-3", title: "Two ways pathogens cause disease", status: "reviewed", caption: "A: a lytic virus enters a host cell, the cell makes new virus particles and then bursts, dying. B: a bacterium in the small intestine releases cholera toxin, which changes how epithelial cells handle chloride ions without destroying them. Many pathogens act in more than one way.", alt: "Left panel: three cells in sequence showing a virus attaching, many virus particles inside the cell, and the cell burst open releasing particles. Right panel: a bacterium in the gut lumen releasing toxin molecules that bind to a row of epithelial cells, with an arrow showing chloride ions leaving a cell.", svg: A.mechanismsFig() },
    ],
    interactives: [entry, mech],
    focus: [
      { slot: "virus-tem", title: "Seeing viruses", ref: R, explanation: () => `<p>Viruses are far too small to resolve with a light microscope: most are about 20–300 nm across, below the roughly 200 nm limit of light microscopy for most of that range. They were first seen with the transmission electron microscope (3.1.2.1), which shows the shape of the capsid and, for enveloped viruses such as influenza, the fuzzy layer of attachment proteins on the surface. ${SC} Rotavirus, a common cause of diarrhoea in young children, was named from the Latin <em>rota</em>, a wheel, after its appearance in electron micrographs. A virus particle on its own cannot do anything: it has no ribosomes and no metabolism, so it can only make copies of itself inside a host cell. That dependence on host cells is why viral disease so often involves damage to the cells that are infected.</p>`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(1, 3), type: "short", marks: 3, stem: "Explain why a virus can only cause disease after it has entered host cells, and give one way in which an infected cell may be damaged. (3 marks)", scheme: [{ point: "Viruses have no ribosomes / enzymes for metabolism / are not cells", marks: 1 }, { point: "They use the host cell's ribosomes, enzymes and ATP to make new virus particles", marks: 1 }, { point: "Damage: cell bursts when the new particles are released (lysis) / cell dies / cell's normal function is lost (e.g. absorptive cells killed)", marks: 1 }], model: "A virus is not a cell: it has no ribosomes and carries out no metabolism of its own. It can only make new virus particles by using the host cell's ribosomes, enzymes and ATP, so it must be inside a host cell. The infected cell may be damaged when many new particles are released and the cell bursts (lysis), killing it, or the cell may be so disrupted that it dies and can no longer carry out its function.", commonErrors: "Saying viruses reproduce by binary fission; saying viruses release toxins as their main mechanism." } },
      { slot: "bacteria-sem", title: "E. coli: mostly harmless, sometimes deadly", ref: R, explanation: () => `<p>${SC} The scanning electron microscope shows bacteria as three-dimensional rods. <em>Escherichia coli</em> is one of the most studied organisms in biology, and most strains live in the human large intestine without causing any harm. A few strains are pathogens. <em>E. coli</em> O157 is usually caught from undercooked beef, unpasteurised milk or contaminated vegetables; it attaches to the lining of the large intestine and releases Shiga toxin, which causes bloody diarrhoea and, in some patients, particularly children, damage to blood vessels and the kidneys. The difference between a harmless and a dangerous strain lies in a small number of genes, including the genes for the toxin. Looking at the bacterium under a microscope cannot tell you which kind it is.</p>`,
        question: { id: `q-${R}-fx2`, ref: R, stmts: S(1, 3, 2), type: "short", marks: 3, stem: "Stretch and challenge. Use the example of E. coli to explain why it is wrong to say that 'bacteria cause disease'. Include how the O157 strain causes harm. (3 marks)", scheme: [{ point: "Most E. coli strains live in the gut without causing disease / most bacteria are harmless", marks: 1 }, { point: "Only some strains are pathogens; O157 is swallowed and enters through the digestive system", marks: 1 }, { point: "O157 releases (Shiga) toxin that damages the intestine / blood vessels / kidneys", marks: 1 }], model: "Most strains of E. coli live in the large intestine of healthy people and cause no disease, so being a bacterium does not make an organism a pathogen. Only some strains cause disease: E. coli O157 is swallowed in contaminated food, enters through the digestive system and releases Shiga toxin, which causes bloody diarrhoea and can damage blood vessels and the kidneys.", commonErrors: "Saying O157 is a virus; implying all E. coli are dangerous." } },
    ],
    examFocus: `<ul><li>Pathogens are <strong>agents of infection</strong> and include <strong>bacteria and viruses</strong>. Not all bacteria are pathogens.</li><li>Learn the three named interfaces: <strong>digestive, reproductive and gas-exchange systems</strong>. Explain entry by the features of the surface (thin, moist, large area, in contact with air, food or body fluids) and the route (inhaled droplets, contaminated food or water, sexual contact).</li><li>Two ways of causing disease: <strong>damaging host cells</strong> (say how: lysis after viral replication, invasion, cells killed) and <strong>producing toxins</strong> (say what the toxin does).</li><li>Use named, accurate examples. The specification names only <strong>cholera</strong> (cholera toxin changes intestinal cell function without destroying the cells; 3.2.3) and <strong>HIV</strong> (destroys helper T cells; 3.2.4). Other examples on this page, such as tetanus toxin acting on the nervous system or poliovirus bursting motor neurones, are stretch and challenge: they show the ideas, but you do not need to learn them, and a question that needs one will give you the facts.</li><li>Never generalise across "all bacteria" or "all viruses". One pathogen may act in more than one way.</li><li>Command words: "describe" the route; "explain" how the feature of the interface or the toxin leads to the symptom.</li></ul>`,
    synoptic: [
      { ref: "3.1.2.2", text: "Structure of prokaryotic cells and of viruses." },
      { ref: "3.1.5.2", text: "Gas-exchange surfaces are large, thin and moist: good for diffusion, and a route for pathogens." },
      { ref: "3.2.2.3", text: "The large absorptive surface of the ileum is also an interface pathogens can reach." },
      { ref: "3.2.3.1", text: "Cholera toxin and chloride ion secretion in detail." },
      { ref: "3.2.4.2", text: "HIV replication inside helper T cells." },
      { ref: "3.2.5.1", text: "Phagocytosis and the immune response to pathogens that cross an interface." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which statement about pathogens is correct?", options: ["Pathogens are agents of infection; they include bacteria and viruses", "All bacteria are pathogens", "Viruses are prokaryotic cells", "Pathogens cause non-infectious diseases such as coronary heart disease"], answer: 0, explanation: "This is the specification's definition. Most bacteria are harmless; viruses are not cells; CHD is not caused by a pathogen." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which three interfaces with the environment does the specification name for a mammal?", options: ["Digestive, reproductive and gas-exchange systems", "Nervous, digestive and circulatory systems", "Skin, eyes and ears", "Kidneys, liver and lungs"], answer: 0, explanation: "These are the three named systems; broken skin is a further route (supporting)." },
      { id: `q-${R}-qc3`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: "Complete the sentence.", text: "Pathogens cause disease by damaging the {{1}} of the host and by producing {{2}}.", answers: { 1: ["cells", "cell", "host cells"], 2: ["toxins", "toxin"] }, explanation: "Damaging host cells; producing toxins." },
      { id: `q-${R}-qc4`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Cholera toxin causes severe diarrhoea. What does it do to the epithelial cells of the small intestine?", options: ["It changes their function, so they secrete more chloride ions; they are not destroyed", "It bursts them, so they die", "It digests their cell walls", "It stops them dividing by mitosis"], answer: 0, explanation: "Cholera is toxin-mediated: water follows the chloride ions into the lumen (3.2.3.1). Animal cells have no cell walls." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "What is a pathogen?", back: "An agent of infection: a microorganism or virus that enters a host and can cause disease. The specification names bacteria and viruses." },
      { id: `f-${R}-2`, front: "Infectious v non-infectious disease (supporting; stretch and challenge examples).", back: "Infectious: caused by a pathogen and can be passed on (cholera, TB, influenza). Non-infectious: not caught from others; several interacting factors (CHD, most cancers)." },
      { id: `f-${R}-3`, front: "Are all bacteria pathogens? (Stretch and challenge examples.)", back: "No. Most bacteria are harmless, and many gut bacteria are useful. Often only some strains of a species cause disease (most E. coli harmless; O157 makes a toxin)." },
      { id: `f-${R}-4`, front: "Three differences between a bacterium and a virus.", back: "Bacterium: a prokaryotic cell, ribosomes, own metabolism, reproduces by binary fission. Virus: not a cell, DNA or RNA in a protein capsid, no ribosomes, replicates only inside a host cell." },
      { id: `f-${R}-5`, front: "Typical sizes of bacteria and viruses.", back: "Bacteria about 1–5 µm long; most viruses about 20–300 nm across (typical values)." },
      { id: `f-${R}-6`, front: "Which interfaces does the specification name in a mammal?", back: "The digestive, reproductive and gas-exchange systems (the list says 'include', so others, such as broken skin, exist)." },
      { id: `f-${R}-7`, front: "Why are interfaces routes for pathogens?", back: "They are thin, moist surfaces in direct contact with air, food, water or another person's body fluids; the gas-exchange and digestive surfaces are also very large." },
      { id: `f-${R}-8`, front: "Gas-exchange system: two pathogens. (Stretch and challenge examples.)", back: "Influenza virus (infects airway epithelial cells); Mycobacterium tuberculosis, a bacterium (survives inside macrophages in the alveoli). Both breathed in as droplets." },
      { id: `f-${R}-9`, front: "Digestive system: three pathogens. (Stretch and challenge examples.)", back: "Vibrio cholerae (bacterium, toxin; on the specification, 3.2.3); poliovirus (can destroy motor neurones); rotavirus (kills villus-tip cells). Swallowed in contaminated food or water." },
      { id: `f-${R}-10`, front: "Reproductive system: three pathogens. (Stretch and challenge examples.)", back: "HIV (virus; destroys helper T cells; on the specification, 3.2.4); Chlamydia trachomatis (bacterium; can scar the oviducts); HPV (virus; risk factor for cervical cancer). Sexual contact." },
      { id: `f-${R}-11`, front: "Skin as a route (supporting; stretch and challenge examples).", back: "Intact skin is a barrier of dead cells; pathogens enter through breaks: Clostridium tetani spores in wounds, rabies virus in bites." },
      { id: `f-${R}-12`, front: "Two ways pathogens cause disease (specification).", back: "By damaging the cells of the host and by producing toxins. Many pathogens do both." },
      { id: `f-${R}-13`, front: "How can a virus damage a host cell?", back: "It uses the cell to make new virus particles; many viruses then burst the cell (lysis), killing it. Others bud, but the cells are still damaged (HIV destroys helper T cells, 3.2.4). Stretch and challenge examples: poliovirus bursts motor neurones; influenza buds." },
      { id: `f-${R}-14`, front: "What is a toxin?", back: "A poisonous molecule (often a protein) released by a pathogen. Only some bacteria, often only some strains, produce toxins." },
      { id: `f-${R}-15`, front: "Cholera toxin: what does it do?", back: "Makes small-intestine epithelial cells secrete more Cl⁻ into the lumen; water follows by osmosis: severe diarrhoea. The cells are not destroyed (3.2.3.1)." },
      { id: `f-${R}-16`, front: "Tetanus toxin: what does it do? (Stretch and challenge examples.)", back: "Made by Clostridium tetani in a wound; travels to the nervous system and blocks release of neurotransmitters that normally inhibit motor neurones, so muscles contract uncontrollably (spasms)." },
      { id: `f-${R}-17`, front: "Give an example of damage caused by the host's immune response (supporting; stretch and challenge examples).", back: "Tuberculosis: much of the lung damage comes from the immune response; chlamydia: inflammation scars the oviducts." },
      { id: `f-${R}-18`, front: "Name two defences at interfaces (supporting).", back: "Mucus and cilia in the airways; stomach acid; harmless gut and vaginal bacteria; the dead outer layer of skin; phagocytes in the alveoli." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which disease is caused by a pathogen?", options: ["Cholera", "Coronary heart disease", "Lung cancer", "Type 2 diabetes"], answer: 0, explanation: "Cholera is caused by a bacterium (3.2.3). The others are non-infectious diseases with several risk factors (3.2.1.2)." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which statement about bacteria is correct?", options: ["Most bacteria are harmless; some species or strains are pathogens", "All bacteria are pathogens because they produce toxins", "Bacteria cannot live inside the human body without causing disease", "Bacteria and viruses are both prokaryotic cells"], answer: 0, explanation: "Most bacteria are not pathogens; viruses are not cells at all." },
      { id: `q-${R}-m3`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which structure is present in a bacterium but absent from a virus particle?", options: ["Ribosomes", "Nucleic acid", "Protein", "Attachment molecules on the surface"], answer: 0, explanation: "Viruses have nucleic acid and protein (capsid, attachment proteins) but no ribosomes, so they need the host cell's ribosomes." },
      { id: `q-${R}-m4`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "The genetic material of a virus is:", options: ["DNA or RNA, depending on the virus", "always DNA", "always RNA", "always circular DNA with plasmids"], answer: 0, explanation: "Some viruses have DNA, others (e.g. HIV, influenza) have RNA. Circular DNA and plasmids are features of bacteria." },
      { id: `q-${R}-m5`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Mycobacterium tuberculosis is a bacterium carried in tiny droplets that infected people cough or breathe out. It usually enters the body through the:", options: ["gas-exchange system", "digestive system", "reproductive system", "unbroken skin"], answer: 0, explanation: "It is breathed in, in droplets from an infected person, so it reaches the gas-exchange system. (Tuberculosis is a stretch and challenge example: the route is given in the stem.)" },
      { id: `q-${R}-m6`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Vibrio cholerae enters the body through the:", options: ["digestive system, in contaminated water or food", "gas-exchange system, in droplets", "reproductive system, during sexual intercourse", "skin, through insect bites"], answer: 0, explanation: "Cholera is spread by the faecal–oral route." },
      { id: `q-${R}-m7`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why can pathogens cross the lining of the reproductive tract more easily than intact skin?", options: ["The lining is a thin, moist mucous membrane without a thick layer of dead cells", "The lining has a larger surface area than the alveoli", "The lining is very acidic", "The lining has no cells"], answer: 0, explanation: "Mucous membranes are thin and moist; intact skin has a tough outer layer of dead cells." },
      { id: `q-${R}-m8`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which feature of the alveoli helps gas exchange but also helps pathogens reach the body?", options: ["A very large, thin, moist surface exposed to inhaled air", "A thick layer of keratinised dead cells", "A low surface area to volume ratio", "A very poor blood supply"], answer: 0, explanation: "The features that speed diffusion also expose a large area to airborne pathogens." },
      { id: `q-${R}-m9`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Hydrochloric acid in the stomach reduces infection through the digestive system because it:", options: ["kills many of the microorganisms swallowed with food and water", "digests the cell walls of all viruses", "makes the intestine impermeable to water", "stops toxins from being made in food before it is eaten"], answer: 0, explanation: "Stomach acid kills many swallowed microorganisms (supporting). Viruses have no cell walls; acid cannot affect a toxin already made in food." },
      { id: `q-${R}-m10`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Stretch and challenge. Tetanus toxin causes muscle spasms because it:", options: ["blocks the release of neurotransmitters that normally inhibit motor neurones", "bursts muscle cells as new bacteria are released", "makes the intestine secrete chloride ions", "destroys helper T cells"], answer: 0, explanation: "With inhibition removed, motor neurones stimulate muscles uncontrollably." },
      { id: `q-${R}-m11`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Stretch and challenge. Poliovirus causes paralysis because:", options: ["new virus particles are released when infected motor neurones burst, destroying them", "it produces a toxin that blocks chloride channels", "it blocks the trachea", "it digests muscle fibres from outside"], answer: 0, explanation: "Lysis of motor neurones means muscles can no longer be stimulated." },
      { id: `q-${R}-m12`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "In cholera, the epithelial cells of the small intestine:", options: ["remain alive, but the toxin changes their ion secretion", "are burst by the multiplying bacteria", "are replaced by bacterial cells", "become impermeable to all ions"], answer: 0, explanation: "Cholera is an example of disease caused by a toxin without destruction of the cells." },
      { id: `q-${R}-m13`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Stretch and challenge. A meal contaminated with Staphylococcus aureus was thoroughly reheated, killing the bacteria, but people who ate it still vomited a few hours later. The best explanation is that:", options: ["a heat-stable toxin made by the bacteria in the food was still present", "the bacteria survived and burst cells of the stomach", "reheating turned the bacteria into viruses", "the people were infected through the gas-exchange system"], answer: 0, explanation: "Some toxins are made in food before it is eaten and survive cooking, so illness does not need living bacteria." },
      { id: `q-${R}-m14`, ref: R, stmts: S(3), type: "mcq", marks: 1, stem: "Stretch and challenge. Much of the lung damage in tuberculosis is caused by:", options: ["the host's immune response to the bacteria", "a toxin that blocks neurotransmitter release", "the bacteria bursting red blood cells", "a virus that infects the alveoli"], answer: 0, explanation: "Tuberculosis is a bacterial disease in which inflammation and the immune response destroy lung tissue (supporting)." },
      { id: `q-${R}-m15`, ref: R, stmts: S(1, 3), type: "mcq", marks: 1, stem: "Which generalisation about pathogens is valid?", options: ["Different pathogens cause disease in different ways, and one pathogen may act in more than one way", "All viruses kill host cells by bursting them", "Only viruses damage host cells; only bacteria produce toxins", "Every bacterium that enters the body causes disease"], answer: 0, explanation: "Influenza and HIV bud rather than burst; Shigella both invades cells and makes a toxin; many exposures cause no disease." },
      { id: `q-${R}-m16`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Stretch and challenge. HIV and Chlamydia trachomatis are both sexually transmitted. Which statement is correct?", options: ["HIV is a virus and Chlamydia is a bacterium; both can enter through the reproductive system", "Both are viruses that enter through the gas-exchange system", "Both are bacteria that enter through the digestive system", "HIV is a bacterium and Chlamydia is a virus"], answer: 0, explanation: "Same interface, different types of pathogen." },
      // ---- gap fills ----
      { id: `q-${R}-g1`, ref: R, stmts: S(1), type: "gap", marks: 3, stem: "Complete the passage.", text: "Pathogens are agents of {{1}}. A bacterium is a prokaryotic {{2}}, whereas a virus has genetic material inside a protein coat called a {{3}}.", answers: { 1: ["infection"], 2: ["cell"], 3: ["capsid"] }, explanation: "Infection; cell; capsid." },
      { id: `q-${R}-g2`, ref: R, stmts: S(2), type: "gap", marks: 3, stem: "Name the interface through which each pathogen usually enters. Influenza virus is breathed in, in droplets; poliovirus is swallowed in contaminated water; HPV is passed on during sexual contact.", text: "Influenza virus: the {{1}} system. Poliovirus: the {{2}} system. HPV: the {{3}} system.", answers: { 1: ["gas-exchange", "gas exchange", "respiratory"], 2: ["digestive"], 3: ["reproductive"] }, explanation: "Inhaled droplets; contaminated food or water; sexual contact." },
      { id: `q-${R}-g3`, ref: R, stmts: S(3), type: "gap", marks: 2, stem: "Complete the sentences.", text: "When many new virus particles are released, the host cell may burst; this is called {{1}}. A poisonous molecule released by a pathogen is called a {{2}}.", answers: { 1: ["lysis"], 2: ["toxin"] }, explanation: "Lysis; toxin." },
      // ---- matching, sequencing, labelling ----
      { id: `q-${R}-mt1`, ref: R, stmts: S(2), type: "match", marks: 4, stem: "Stretch and challenge. Match each pathogen to the interface it usually crosses.", pairs: [{ left: "Influenza virus", right: "Gas-exchange system, in inhaled droplets" }, { left: "Vibrio cholerae", right: "Digestive system, in contaminated water" }, { left: "HIV", right: "Reproductive system, during sexual intercourse" }, { left: "Clostridium tetani", right: "Skin, through a deep wound" }] },
      { id: `q-${R}-mt2`, ref: R, stmts: S(3), type: "match", marks: 4, stem: "Stretch and challenge. Match each pathogen to the main way it causes harm.", pairs: [{ left: "Poliovirus", right: "Bursts motor neurones as new virus particles are released" }, { left: "Vibrio cholerae", right: "Toxin makes intestinal cells secrete chloride ions; the cells survive" }, { left: "Clostridium tetani", right: "Toxin travels to the nervous system and causes muscle spasms" }, { left: "Mycobacterium tuberculosis", right: "Lung tissue destroyed largely by the host's immune response" }] },
      { id: `q-${R}-sq1`, ref: R, stmts: S(3), type: "sequence", marks: 4, stem: "Put the stages of host-cell damage by a lytic virus in order.", steps: ["Attachment proteins on the virus bind to receptors on the host cell", "The viral genetic material enters the host cell", "The host cell's ribosomes and enzymes make viral proteins and copies of the genetic material", "New virus particles are assembled inside the cell", "The cell bursts (lysis), releasing new virus particles and killing the cell"] },
      { id: `q-${R}-lab1`, ref: R, stmts: S(2), type: "label", drag: true, marks: 4, stem: "Label the four numbered interfaces through which pathogens can enter a mammal.", svg: A.interfacesFig({ numbers: true }), labels: [{ n: 1, answer: "Gas-exchange system" }, { n: 2, answer: "Digestive system" }, { n: 3, answer: "Reproductive system" }, { n: 4, answer: "Broken skin" }], bank: ["Gas-exchange system", "Digestive system", "Reproductive system", "Broken skin", "Circulatory system", "Nervous system"] },
      // ---- short answers ----
      { id: `q-${R}-s1`, ref: R, stmts: S(1), type: "short", marks: 3, stem: "Give three differences between the structure of a bacterium and the structure of a virus particle. (3 marks)", scheme: [{ point: "Bacterium is a cell (prokaryotic); a virus is not a cell / is acellular", marks: 1 }, { point: "Bacterium has ribosomes (and cytoplasm); a virus has none", marks: 1 }, { point: "Bacterium has DNA (circular, often plasmids) and a cell wall / membrane; a virus has DNA or RNA inside a protein capsid (some with an envelope and attachment proteins)", marks: 1 }], model: "A bacterium is a prokaryotic cell with a cell wall, cell-surface membrane and cytoplasm, whereas a virus particle is not a cell. A bacterium contains ribosomes; a virus has none. A bacterium's DNA is a circular molecule free in the cytoplasm, often with plasmids, while a virus has either DNA or RNA enclosed in a protein capsid, with attachment proteins and, in some viruses, a lipid envelope.", commonErrors: "Saying viruses have a nucleus or that bacteria have a capsid." },
      { id: `q-${R}-s2`, ref: R, stmts: S(2), type: "short", marks: 3, stem: "Explain why the digestive and gas-exchange systems are common routes of entry for pathogens. (3 marks)", scheme: [{ point: "Both are interfaces in direct contact with material from the environment (food and water / inhaled air)", marks: 1 }, { point: "Pathogens are carried in with that material: contaminated food or water; airborne droplets", marks: 1 }, { point: "The surfaces are large, thin and moist (adapted for absorption / diffusion), which pathogens can reach and cross", marks: 1 }], model: "Both systems are interfaces between the body and the environment: food and water pass through the digestive system and air through the gas-exchange system. Pathogens carried in contaminated food or water, or in airborne droplets, are therefore brought into contact with these surfaces. The surfaces are large, thin and moist because they are adapted for absorption and diffusion, which also makes them easier for pathogens to reach and cross than intact skin.", commonErrors: "Describing only defences; not naming what carries the pathogen." },
      { id: `q-${R}-s3`, ref: R, stmts: S(3, 2), type: "short", marks: 3, stem: "Stretch and challenge. A gardener cut her hand on a rusty tool in soil and, ten days later, developed spasms in the muscles of her jaw and back. Explain how a bacterium in the wound could cause these symptoms. (3 marks)", scheme: [{ point: "Clostridium tetani (spores from soil) entered through the broken skin / wound", marks: 1 }, { point: "The bacteria release a toxin (tetanus toxin)", marks: 1 }, { point: "The toxin travels to the nervous system and blocks release of neurotransmitters that normally inhibit motor neurones, so muscles contract uncontrollably", marks: 1 }], model: "Spores of Clostridium tetani in the soil entered through the cut, which broke the barrier of the skin. In the wound the bacteria grew and released tetanus toxin. The toxin travelled to the nervous system, where it stopped the release of neurotransmitters that normally inhibit motor neurones, so muscles far from the wound, such as those of the jaw and back, contracted uncontrollably.", commonErrors: "Saying the bacteria spread to the jaw muscles and burst them; saying tetanus is caused by rust." },
      { id: `q-${R}-s4`, ref: R, stmts: S(3), type: "short", marks: 4, stem: "Stretch and challenge. Compare how Vibrio cholerae and poliovirus cause disease. (4 marks)", scheme: [{ point: "Vibrio cholerae is a bacterium; poliovirus is a virus (both enter through the digestive system)", marks: 1 }, { point: "V. cholerae produces a toxin (cholera toxin) that acts on epithelial cells of the small intestine", marks: 1 }, { point: "The toxin changes cell function (more Cl⁻ secreted, water follows, diarrhoea); the cells are not destroyed", marks: 1 }, { point: "Poliovirus replicates inside host cells (motor neurones) and destroys them by lysis, causing paralysis", marks: 1 }], model: "Both are swallowed and enter through the digestive system, but Vibrio cholerae is a bacterium and poliovirus is a virus. Vibrio cholerae causes disease through a toxin: cholera toxin acts on the epithelial cells of the small intestine and makes them secrete more chloride ions, so water follows into the lumen and severe diarrhoea results, without the cells being destroyed. Poliovirus damages host cells directly: it replicates inside cells and, in motor neurones, the cells burst as new particles are released, so the neurones are destroyed and paralysis can result.", commonErrors: "Saying cholera bacteria burst intestinal cells." },
      { id: `q-${R}-s5`, ref: R, stmts: S(1, 3), type: "short", marks: 3, stem: "Evaluate the statement: 'Bacteria cause disease by producing toxins, so any bacterium in the body is dangerous.' (3 marks)", scheme: [{ point: "Partly true: some bacteria cause disease by producing toxins (e.g. cholera, tetanus)", marks: 1 }, { point: "But some bacteria cause disease mainly by invading / damaging cells or through the immune response (e.g. Shigella, tuberculosis)", marks: 1 }, { point: "And most bacteria (e.g. most gut E. coli strains) are harmless; only some species or strains are pathogens", marks: 1 }], alternatives: "Named examples are not required; the specification example is cholera. Examples such as tetanus, Shigella, tuberculosis and E. coli are stretch and challenge: credit them when accurate.", model: "The statement is partly true: some bacteria do cause disease by producing toxins, such as Vibrio cholerae and Clostridium tetani. However, toxins are not the only mechanism: Shigella invades and destroys cells lining the colon, and in tuberculosis much of the damage is caused by the immune response. Most importantly, most bacteria are not pathogens at all: most strains of E. coli live in the gut without causing disease. So a bacterium in the body is not necessarily dangerous.", commonErrors: "Agreeing with the statement; giving only toxin examples." },
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(1, 2, 3), type: "extended", marks: 6, stem: "Extended response. Using named examples, describe how pathogens can enter the body of a mammal and explain how they then cause disease. (6 marks)", scheme: [{ point: "Pathogens are agents of infection, including bacteria and viruses; they must cross an interface with the environment", marks: 1 }, { point: "Gas-exchange system: pathogens carried in inhaled droplets reach a large, thin, moist surface (a named example is not required here; e.g. influenza virus / M. tuberculosis)", marks: 1 }, { point: "Digestive system: contaminated food or water, e.g. cholera bacteria (Vibrio cholerae) / poliovirus / rotavirus", marks: 1 }, { point: "Reproductive system: sexual contact with thin mucous membranes, e.g. HIV / Chlamydia / HPV", marks: 1 }, { point: "Damage to host cells explained with an example: e.g. virus replicates and cell bursts (poliovirus, motor neurones) / HIV destroys helper T cells / Shigella invades colon cells", marks: 1 }, { point: "Toxins explained with an example: e.g. cholera toxin increases Cl⁻ secretion without killing cells / tetanus toxin blocks inhibitory neurotransmitter release; note that pathogens differ and may act in more than one way", marks: 1 }], levels: "Level 3 (5–6): all three named interfaces with correct examples, and both mechanisms explained with accurate examples; no over-generalisation. Level 2 (3–4): at least two interfaces and one mechanism explained, or all described without explanation. Level 1 (1–2): isolated correct points.", model: "Pathogens, such as bacteria and viruses, are agents of infection; to cause disease they must penetrate one of the body's interfaces with the environment. The gas-exchange system has a large, thin, moist surface exposed to inhaled air, so influenza virus and Mycobacterium tuberculosis can enter in droplets breathed out by infected people. The digestive system is reached by pathogens in contaminated food or water, such as Vibrio cholerae and poliovirus. The reproductive system is lined by thin mucous membranes that HIV, HPV and Chlamydia can cross during sexual contact. Once inside, some pathogens damage host cells: poliovirus replicates inside motor neurones, which burst as new particles are released, causing paralysis, and HIV destroys helper T cells. Others produce toxins: cholera toxin makes intestinal epithelial cells secrete more chloride ions so that water follows and severe diarrhoea results, without killing the cells, while tetanus toxin from bacteria in a wound blocks the release of inhibitory neurotransmitters, causing muscle spasms. Different pathogens act in different ways, and some, such as Shigella, both damage cells and produce a toxin.", alternatives: "Cholera and HIV are the only diseases named in the specification, and they are enough for full marks (with the gas-exchange route described without a named example). Other named pathogens are stretch and challenge examples: credit them when accurate, but no mark requires them.", commonErrors: "Listing pathogens without the interface or mechanism; claiming all bacteria make toxins." },
    ],
  };
})();
